// Populate each style's back/neck/ring/pocket/hands/head/ammo/feet slots with
// items from UNIVERSAL_ACCESSORIES, filtered to items whose applicableStyles
// includes that style. Concatenated (not assigned) since hands/head/ammo/feet
// already have per-style entries defined directly above.
for (const style of COMBAT_STYLES) {
  for (const slot of ['back', 'neck', 'ring', 'pocket', 'hands', 'head', 'ammo', 'feet', 'torso', 'legs']) {
    GEAR[style][slot] = [
      ...GEAR[style][slot],
      ...UNIVERSAL_ACCESSORIES.filter((item) => item.slot === slot && item.applicableStyles.includes(style)),
    ];
  }
}
